(()=>{
'use strict';let active=null;const KEY='yugen-entrance-v6';
const landscape=`<picture class="entrance-art-picture"><source media="(max-width: 650px)" srcset="assets/entrance-landscape-v6-mobile.webp"><img class="entrance-art-image" src="assets/entrance-landscape-v6.webp" alt="" decoding="async" fetchpriority="high"></picture>`;
function open(force=false){const home=document.body.dataset.page==='home';if(!home){if(force)location.assign('index.html?entrada=1');return}if(active)return;let seen=false;try{seen=sessionStorage.getItem(KEY)==='entered'}catch{}if(seen&&!force){document.body.classList.add('page-ready');return}if(document.querySelector('dialog[open]')){if(force)return;document.body.classList.add('page-ready');return}
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const previousOverflow=document.documentElement.style.overflow;const dialog=document.createElement('dialog');dialog.id='intro-portal';dialog.className='intro-portal entrance-v5 entrance-v6';dialog.setAttribute('aria-labelledby','entrance-title');dialog.setAttribute('aria-describedby','entrance-description');const petals=Array.from({length:13},(_,i)=>'<i style="--petal-x:'+((i*73+17)%97)+'%;--petal-delay:'+(-i*1.3)+'s;--petal-time:'+(12+i%5)+'s;--petal-turn:'+(i%2?'-1':'1')+'"></i>').join('');
dialog.innerHTML='<div class="entrance-paper" aria-hidden="true"></div><div class="entrance-frame" aria-hidden="true"></div><div class="entrance-header"><span class="entrance-signature"><b aria-hidden="true">幽</b> YŪGEN <small>JAPÃO ALÉM DO ÓBVIO</small></span><button class="entrance-skip" aria-label="Pular entrada e ir para o site">Pular entrada <span aria-hidden="true">↗</span></button></div><div class="entrance-layout"><div class="entrance-scene" aria-hidden="true">'+landscape+'<div class="entrance-fog fog-one"></div><div class="entrance-fog fog-two"></div></div><div class="entrance-copy"><p class="entrance-kicker"><span></span> ENTRE A TINTA, A LUZ E O INESPERADO</p><h2 id="entrance-title"><span class="entrance-line"><span>Um passo.</span></span><span class="entrance-line"><span>Outro mundo.</span></span><span class="entrance-line"><span><em>O seu Japão.</em></span></span></h2><p class="entrance-description" id="entrance-description">Entre o que você conhece<br>e o que ainda vai te encantar,<br> existe uma travessia.</p><button class="entrance-enter"><span>Começar a travessia</span><span class="entrance-button-orbit" aria-hidden="true">↗</span></button><p class="entrance-caption">SEM PRESSA. COM TODOS OS SENTIDOS.</p></div></div><div class="entrance-petals" aria-hidden="true">'+petals+'</div><div class="entrance-footer"><span>01 / O PRIMEIRO ENCONTRO</span><span class="entrance-footer-center">見る・感じる・見つける</span><span>UM INSTANTE. INFINITOS CAMINHOS.</span></div><span class="entrance-status" role="status" aria-live="polite"></span>';
document.body.append(dialog);const art=dialog.querySelector('.entrance-art-image');const revealArt=()=>{if(dialog.isConnected)dialog.classList.add('art-ready')};if(art.complete&&art.naturalWidth)revealArt();else art.addEventListener('load',revealArt,{once:true});active=dialog;document.documentElement.style.overflow='hidden';document.body.classList.remove('page-ready');document.body.classList.add('intro-running');dialog.showModal();dialog.querySelector('.entrance-enter').focus({preventScroll:true});let closing=false,frame=0,watchdog;const controller=new AbortController();const initialHash=location.hash;function remember(){try{sessionStorage.setItem(KEY,'entered')}catch{}}
function clean(){cancelAnimationFrame(frame);clearTimeout(watchdog);controller.abort();if(dialog.open)dialog.close();dialog.remove();active=null;document.documentElement.style.overflow=previousOverflow;document.body.classList.remove('intro-running');document.body.classList.add('page-ready');document.body.classList.toggle('body-modal-lock',!!document.querySelector('dialog[open]'));const url=new URL(location.href);if(url.searchParams.has('entrada')){url.searchParams.delete('entrada');history.replaceState(null,'',url.pathname+url.search+url.hash)}if(force)document.querySelector('.hero .button')?.focus({preventScroll:true});else if(initialHash)document.getElementById(initialHash.slice(1))?.scrollIntoView({behavior:'instant'});else document.querySelector('.hero .button')?.focus({preventScroll:true})}
function finish(animate){if(closing)return;closing=true;remember();if(!animate||reduced){clean();return}dialog.querySelector('.entrance-status').textContent='A travessia começou. Bem-vindo ao Yūgen.';dialog.classList.add('entering');if(force||!initialHash)window.scrollTo({top:0,behavior:'instant'});const begin=performance.now();function iris(now){const t=Math.max(0,Math.min(1,(now-begin-180)/1420));const eased=t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;dialog.style.setProperty('--iris-radius',(eased*155).toFixed(3)+'vmax');if(t<1)frame=requestAnimationFrame(iris);else clean()}frame=requestAnimationFrame(iris);watchdog=setTimeout(clean,2100)}
dialog.querySelector('.entrance-enter').addEventListener('click',()=>finish(true));dialog.querySelector('.entrance-skip').addEventListener('click',()=>finish(false));dialog.addEventListener('cancel',e=>{e.preventDefault();finish(false)});
if(!reduced&&matchMedia('(pointer:fine)').matches){let pending=false;dialog.addEventListener('pointermove',e=>{if(closing||pending)return;pending=true;const x=(e.clientX/innerWidth-.5)*2,y=(e.clientY/innerHeight-.5)*2;requestAnimationFrame(()=>{if(dialog.isConnected){dialog.style.setProperty('--scene-x',(x*6).toFixed(2)+'px');dialog.style.setProperty('--scene-y',(y*4).toFixed(2)+'px')}pending=false})},{signal:controller.signal});dialog.addEventListener('pointerleave',()=>{dialog.style.setProperty('--scene-x','0px');dialog.style.setProperty('--scene-y','0px')},{signal:controller.signal})}
}
window.YugenEntrance={open};
})();
